function resolveEvidenceAtDate(eid,mc,referenceDate){const observations=rowsAtReferenceDate(eid,mc,referenceDate),referenceDateOut=observations[0]?.reference_date||referenceDate||null;if(!observations.length)return{state:'NONE',entity_id:eid,metric_code:mc,reference_date:referenceDateOut,observations:[],governance:null,reason:'NO_OBSERVATION'};if(observations.length===1)return{state:'SINGLE',entity_id:eid,metric_code:mc,reference_date:referenceDateOut,observations,governance:null,reason:null};const governance=unresolvedGovernanceForRows(eid,observations);return governance?{state:'UNRESOLVED_CONFLICT',entity_id:eid,metric_code:mc,reference_date:referenceDateOut,observations,governance,reason:'UNRESOLVED_SOURCE_CONFLICT'}:{state:'MULTIPLE_ROWS',entity_id:eid,metric_code:mc,reference_date:referenceDateOut,observations,governance:null,reason:'MULTIPLE_ROWS_AT_REFERENCE_DATE'}}
