function p3dhPairStatus(a,b){if(!a||!b)return{status:'UNRESOLVED',reasons:['MISSING_OBSERVATION']};const reasons=[];if(a.reference_date!==b.reference_date)reasons.push('REFERENCE_DATE_DIFF');if(a.unit!==b.unit)reasons.push('UNIT_DIFF');if((a.currency||'')!==(b.currency||''))reasons.push('CURRENCY_DIFF');if((a.consolidation_scope||'')!==(b.consolidation_scope||''))reasons.push('CONSOLIDATION_SCOPE_DIFF');const sa=a.semantic||{},sb=b.semantic||{};if((sa.reporting_framework||'')!==(sb.reporting_framework||''))reasons.push('REPORTING_FRAMEWORK_DIFF');if((sa.period_type||'')!==(sb.period_type||''))reasons.push('PERIOD_TYPE_DIFF');if((sa.variant_key||'')!==(sb.variant_key||''))reasons.push('VARIANT_KEY_DIFF');if((sa.semantic_fingerprint||'')!==(sb.semantic_fingerprint||''))reasons.push('SEMANTIC_FINGERPRINT_DIFF');if(reasons.some(x=>['UNIT_DIFF','CURRENCY_DIFF','REFERENCE_DATE_DIFF'].includes(x)))return{status:'NOT_COMPARABLE',reasons};return reasons.length?{status:'APPROXIMATE_ONLY',reasons}:{status:'EXACTLY_COMPARABLE',reasons:[]}}
function compareP3DHLocal(mc,ids){const chosen=latestCommonReferenceDate(mc,ids),resolutions=ids.map(id=>chosen?resolveEvidenceAtDate(id,mc,chosen):resolveLatestEvidence(id,mc)),obs=resolutions.map(r=>ordinaryScalarAllowed(r)?r.observations[0]:null),pairs=[];let overall='EXACTLY_COMPARABLE';const rank={EXACTLY_COMPARABLE:0,APPROXIMATE_ONLY:1,UNRESOLVED:2,NOT_COMPARABLE:3},unresolvedReason=r=>r.state==='UNRESOLVED_CONFLICT'?'UNRESOLVED_SOURCE_CONFLICT':r.state==='MULTIPLE_ROWS'?'MULTIPLE_LATEST_ROWS':'MISSING_OBSERVATION';for(const r of resolutions)if(!ordinaryScalarAllowed(r)&&rank.UNRESOLVED>rank[overall])overall='UNRESOLVED';for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++){let c;if(!ordinaryScalarAllowed(resolutions[i])||!ordinaryScalarAllowed(resolutions[j])){const reasons=[!ordinaryScalarAllowed(resolutions[i])?unresolvedReason(resolutions[i]):null,!ordinaryScalarAllowed(resolutions[j])?unresolvedReason(resolutions[j]):null].filter(Boolean);c={status:'UNRESOLVED',reasons:[...new Set(reasons)]}}else c=p3dhPairStatus(obs[i],obs[j]);pairs.push({a:ids[i],b:ids[j],...c,comparative_delta:null,winner_loser:null});if(rank[c.status]>rank[overall])overall=c.status}return{metric_code:mc,reference_date:chosen,observations:obs,resolutions,evidence_rows:resolutions.flatMap(r=>r.observations||[]),pairwise:pairs,overall_status:overall,cross_sectional_comparison_only:true,historical_continuity_status:'UNRESOLVED_NO_BANKING_TIME_SERIES_DECISIONS',comparative_delta:null,statistics_authorized:false,statistics:null,ranking_authorized:false,notice:'Source-bound Banking facts are compared only at one common reference date. Multiple evidence rows are never silently collapsed. Ranking and peer statistics remain withheld; no historical arithmetic is inferred.'}}

function compareLocal(mc,ids){return String(mc||'').startsWith('EBA_P3DH_')?compareP3DHLocal(mc,ids):compareGenericLocal(mc,ids)}
async function runCompare(ids){const mc=$('#cmpMetric').value,r=state.runtime==='local'?await api('/api/compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({metric_code:mc,entity_ids:ids})}):compareLocal(mc,ids);const groups=r.resolutions||null,cards=groups?groups.map(x=>resolutionCardsHtml(x)).join(''):`<div class="card-grid">${(r.observations||[]).map(factCard).join('')}</div>`;const p=comparisonPresentation(r.overall_status),reasons=[...new Set((r.pairwise||[]).flatMap(x=>x.reasons||[]))],reasonHtml=reasons.length?`<ul>${reasons.map(x=>`<li>${esc(reasonLabel(x))}</li>`).join('')}</ul>`:`<p>${esc(t('plainNoReasons'))}</p>`,firstObs=(r.observations||[]).find(Boolean);$('#compareResult').innerHTML=`<section class="comparability-summary ${p.cls}"><div class="eyebrow">${t('comparisonAssessment')}</div><h4>${esc(p.title)}</h4><p>${esc(p.text)}</p><details class="progressive reason-details"><summary>${t('whyStatus')}</summary>${reasonHtml}</details><div class="next-actions"><span>${t('nextSteps')}</span><button type="button" class="mini guided-next" data-next="investigate">${t('nextInvestigate')}</button>${firstObs?`<button type="button" class="mini guided-next" data-next="audit" data-oid="${esc(firstObs.id)}">${t('nextAudit')}</button>`:''}</div></section>${cards}<details class="progressive technical-comparison"><summary>${t('technicalDetails')}</summary><div class="compare-status">${badge(r.overall_status,r.overall_status==='EXACTLY_COMPARABLE'?'good':r.overall_status==='NOT_COMPARABLE'?'bad':'warn')} ${r.statistics_authorized?badge(t('statisticsAuthorized'),'good'):badge(t('statisticsWithheld'),'warn')} ${badge(t('rankingClosed'),'bad')}</div><div class="pair-list">${(r.pairwise||[]).map(p=>`<div><b>${esc(nameOf(p.a))} ↔ ${esc(nameOf(p.b))}</b>${badge(p.status)}<small>${esc((p.reasons||[]).join(', '))}</small></div>`).join('')}</div>${r.statistics?`<pre>${esc(JSON.stringify(r.statistics,null,2))}</pre>`:''}</details>`;bindAuditLinks();bindGuidedNext();updateContextBar()}
function svgSeries(xs){const ys=xs.filter(o=>o.numeric_value_real!=null);if(ys.length<2)return`<div class="empty">${t('noResults')}</div>`;const W=760,H=230,p=30,min=Math.min(...ys.map(o=>Number(o.numeric_value_real))),max=Math.max(...ys.map(o=>Number(o.numeric_value_real))),span=max-min||1,pts=ys.map((o,i)=>[p+i*(W-2*p)/(ys.length-1),H-p-(Number(o.numeric_value_real)-min)*(H-2*p)/span,o]),path=pts.map((x,i)=>(i?'L':'M')+x[0].toFixed(1)+','+x[1].toFixed(1)).join(' ');return`<svg viewBox="0 0 ${W} ${H}" class="chart"><path d="${path}" fill="none" stroke="currentColor" stroke-width="3"/>${pts.map(x=>`<circle cx="${x[0]}" cy="${x[1]}" r="4"><title>${esc(x[2].reference_date)} · ${fmt(x[2].numeric_value_real)}</title></circle>`).join('')}</svg><div class="series-table">${ys.map(o=>`<div><span>${esc(o.reference_date)}</span><b>${val(o)}</b><small>${esc(o.restatement_version||'')}</small></div>`).join('')}</div>`}
function connectedRelations(eid){const rel=state.snapshot.relations.filter(r=>String(r.status||'').startsWith('ACTIVE')),adj=new Map();rel.forEach(r=>{if(!adj.has(r.subject_entity_id))adj.set(r.subject_entity_id,new Set());if(!adj.has(r.object_entity_id))adj.set(r.object_entity_id,new Set());adj.get(r.subject_entity_id).add(r.object_entity_id);adj.get(r.object_entity_id).add(r.subject_entity_id)});const seen=new Set([eid]),stack=[eid];while(stack.length){const x=stack.pop();for(const y of adj.get(x)||[])if(!seen.has(y)){seen.add(y);stack.push(y)}}return rel.filter(r=>seen.has(r.subject_entity_id)&&seen.has(r.object_entity_id))}
function ownershipSvg(eid){const rel=connectedRelations(eid);if(!rel.length)return`<div class="empty">${t('noResults')}</div>`;const nodes=[...new Set(rel.flatMap(r=>[r.subject_entity_id,r.object_entity_id]))],W=760,H=Math.max(240,nodes.length*65),pos=new Map(nodes.map((n,i)=>[n,[i%2?520:150,55+i*55]]));return`<svg viewBox="0 0 ${W} ${H}" class="graph">${rel.map(r=>{const a=pos.get(r.subject_entity_id),b=pos.get(r.object_entity_id);return`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}"/><text x="${(a[0]+b[0])/2}" y="${(a[1]+b[1])/2-5}">${esc(r.relation_type)}${r.ownership_percent!=null?' '+fmt(r.ownership_percent)+'%':''}</text>`}).join('')}${nodes.map(n=>{const p=pos.get(n);return`<circle cx="${p[0]}" cy="${p[1]}" r="8"/><text x="${p[0]+14}" y="${p[1]+4}">${esc(nameOf(n))}</text>`}).join('')}</svg>`}
function componentMetricValueHtml(eid,mc){const r=resolveLatestEvidence(eid,mc);if(r.state==='NONE')return'—';if(r.state==='SINGLE')return val(r.observations[0]);return`${esc(r.state==='UNRESOLVED_CONFLICT'?t('unresolvedShort'):t('multipleRowsShort'))} · ${r.observations.length}`};function componentHtml(eid){const obs=state.snapshot.observations.filter(o=>o.entity_id===eid),groups={};obs.forEach(o=>(metricOf(o.metric_code).families||['UNCLASSIFIED']).forEach(f=>{groups[f]??={};groups[f][o.metric_code]??=[];groups[f][o.metric_code].push(o)}));return Object.keys(groups).sort().map(f=>`<details><summary>${esc(f)} · ${Object.keys(groups[f]).length}</summary>${Object.entries(groups[f]).sort().map(([mc,xs])=>{xs.sort((a,b)=>(a.reference_date||'').localeCompare(b.reference_date||''));return`<div class="component-row"><b>${esc(metricOf(mc).name||mc)}</b><span>${componentMetricValueHtml(eid,mc)}</span><small>${esc(xs[0]?.reference_date||'')} → ${esc(xs.at(-1)?.reference_date||'')}</small></div>`}).join('')}</details>`).join('')||`<div class="empty">${t('noResults')}</div>`}
function metricHtml(mc){const m=metricOf(mc),xs=state.snapshot.observations.filter(o=>o.metric_code===mc),eids=new Set(xs.map(o=>o.entity_id)),periods=[...new Set(xs.map(o=>o.reference_date).filter(Boolean))].sort();return`<article class="card"><h4>${esc(m.name||m.code)}</h4><code>${esc(m.code)}</code><p>${esc(m.definition||'')}</p><div class="badges">${(m.families||[]).map(x=>badge(x)).join('')}</div><div class="kv"><span>${t('institution')}</span><b>${eids.size}</b><span>${t('facts')}</span><b>${xs.length}</b><span>${t('periods')}</span><b>${periods[0]||'—'} → ${periods.at(-1)||'—'}</b></div></article>`}
function fi3StatusText(r){return state.lang==='de'?(r.public_status_de||t('fi3Candidate')):(r.public_status_en||t('fi3Candidate'))}
function fi3GroupableHoldRole(r,byCandidate){
  const x=byCandidate.get(r.candidate_id);
  return r.decision_status==='HOLD_INSUFFICIENT_IDENTITY_EVIDENCE'&&r.source_family==='KOHESIO'&&r.source_role==='BENEFICIARY'&&r.project_id==null&&r.amount_text==null&&r.currency==null&&r.amount_publication==='WITHHELD_IDENTITY_HOLD_PUBLIC'&&x?.source_legal_name==null;
}
function fi3ContextHtml(eid){
  const p=state.fi3;
  if(!p)return`<h4>${t('fi3Title')}</h4><div class="empty">${t('fi3NoCandidate')}</div>`;
  const ids=(p.identity_candidates||[]).filter(x=>x.canonical_entity_id===eid);
  const roles=(p.role_assertions||[]).filter(x=>x.canonical_entity_id===eid);
  const byCandidate=new Map(ids.map(x=>[x.candidate_id,x]));
  const identityCards=ids.map(x=>`<article class="candidate"><div class="eyebrow">${esc(x.source_family||'')} · ${esc(x.source_role||'')}</div>${badge(t('fi3Candidate'),'warn')}<h4>${esc(x.source_legal_name||t('fi3Candidate'))}</h4><small>${esc(x.source_country||'')}</small><div class="kv"><span>${t('fi3Decision')}</span><b>${esc(fi3StatusText(x))}</b><span>${t('fi3EvidenceRows')}</span><b>${esc(x.evidence_row_count??'—')}</b></div><code>${esc(x.candidate_id)}</code></article>`).join('');
  const groupedHoldRoles=roles.filter(r=>fi3GroupableHoldRole(r,byCandidate));
  const ordinaryRoles=roles.filter(r=>!fi3GroupableHoldRole(r,byCandidate));
  const groupedHoldCard=groupedHoldRoles.length?`<article class="candidate fi3-hold-group"><div class="eyebrow">KOHESIO · BENEFICIARY</div>${badge(t('fi3Candidate'),'warn')}<h4>${esc(t('fi3HoldGroupTitle'))}</h4><div class="kv"><span>${esc(t('fi3HoldGroupRows'))}</span><b>${esc(groupedHoldRoles.length)}</b><span>${t('fi3Decision')}</span><b>${esc(fi3StatusText(groupedHoldRoles[0]))}</b><span>${t('fi3Amount')}</span><b>${esc(t('fi3AmountWithheld'))}</b></div><details><summary>${esc(t('fi3HoldGroupDetails'))}</summary><ul>${groupedHoldRoles.map(r=>`<li><code>${esc(r.role_assertion_id)}</code> · <code>${esc(r.candidate_id)}</code></li>`).join('')}</ul></details></article>`:'';
  const roleCards=ordinaryRoles.map(r=>{const x=byCandidate.get(r.candidate_id),amountText=r.amount_publication==='WITHHELD_IDENTITY_HOLD_PUBLIC'?t('fi3AmountWithheld'):([r.amount_text,r.currency].filter(Boolean).join(' ')||'—');return`<article class="candidate"><div class="eyebrow">${esc(r.source_family||'')} · ${esc(r.source_role||'')}</div>${badge(t('fi3Candidate'),'warn')}<h4>${esc(r.project_id||x?.source_legal_name||t('fi3Candidate'))}</h4><small>${esc(x?.source_legal_name||'')}</small><div class="kv"><span>${t('fi3Decision')}</span><b>${esc(fi3StatusText(r))}</b><span>${t('fi3Amount')}</span><b>${esc(amountText)}</b></div><code>${esc(r.role_assertion_id)}</code></article>`}).join('');
  const rs=p.reject_summary||{};
  const rejectReasons=Object.entries(rs.reason_classes||{}).map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');
  return`<h4>${t('fi3Title')}</h4><p class="muted">${t('fi3Help')}</p>${(ids.length||roles.length)?`<div class="candidate-grid">${identityCards}${groupedHoldCard}${roleCards}</div>`:`<div class="empty">${t('fi3NoCandidate')}</div>`}<details><summary>${t('fi3RejectSummary')} · ${esc(rs.identity_count??0)}</summary><p class="muted">${t('fi3RejectPrivacy')}</p><div class="decision-list">${rejectReasons}</div></details>`;
}

function researchContextHtml(eid){
 const R=state.research;if(!R)return'';
 const L=(de,en)=>state.lang==='de'?de:en,fi2=R.fi2?.by_entity?.[eid],net=R.network?.by_entity?.[eid],cov=R.coverage?.by_entity?.[eid],f=R.fi1||{},fs=f.source_state||{};
 const fmtM=v=>v==null?'—':fmt(v)+' Mio. EUR';
 const tedHref=u=>{try{const x=new URL(String(u||''));return x.protocol==='https:'&&x.hostname==='ted.europa.eu'?x.href:null}catch{return null}};
 const fi2Notices=(fi2?.notices||[]).map(x=>{const h=tedHref(x.source_url),d=String(x.publication_date||'').slice(0,10),label=esc(x.publication_number||'—');return`<div><span>${h?`<a href="${esc(h)}" target="_blank" rel="noopener noreferrer">${label}</a>`:label}${d?' · '+esc(d):''}</span><b>${esc(x.notice_type||'TED')}</b></div>`}).join('');
 const fi2Html=fi2?`<article class="card"><h4>FI2 · TED</h4><p class="muted">${esc(L('Quellengebundene Rollen-/Vergabekontexte; keine Buyer→Winner-Kante und keine Betragsaggregation.','Source-bound role/procurement context; no buyer→winner edge and no amount aggregation.'))}</p><div class="kv"><span>${esc(L('Bestätigte Identitäts-/Rollenbindungen','Confirmed identity/role bindings'))}</span><b>${esc(fi2.confirmed_identity_assertions)}</b><span>${esc(L('TED-Bekanntmachungen','TED notices'))}</span><b>${esc(fi2.publication_count)}</b><span>${esc(L('Winner-Ereignisse (nur Anzahl)','Winner events (count only)'))}</span><b>${esc(fi2.winner_event_count)}</b></div><details><summary>${esc(L('Bekanntmachungsreferenzen','Notice references'))}</summary><div class="decision-list">${fi2Notices||'—'}</div></details></article>`:`<article class="card"><h4>FI2 · TED</h4><div class="empty">${esc(L('Keine bestätigte FI2/TED-Rollenbindung für diese Institution in der statischen Projektion.','No confirmed FI2/TED role binding for this institution in the static projection.'))}</div></article>`;
 const networkParts=[];
 if(net?.sovereign)networkParts.push(`<div><b>${esc(L('EBA-Staatsexposure','EBA sovereign exposure'))}</b><small>${esc(net.sovereign.reference_date)} · ${esc(net.sovereign.row_count)} rows · ${fmtM(net.sovereign.signed_total_million_eur)}</small></div>`);
 if(net?.credit_geography)networkParts.push(`<div><b>${esc(L('EBA-Kreditgeografie','EBA credit geography'))}</b><small>${esc(net.credit_geography.reference_date)} · ${esc(net.credit_geography.row_count)} rows</small></div>`);
 if(net?.nace)networkParts.push(`<div><b>${esc(L('EBA-NACE-Kontext','EBA NACE context'))}</b><small>${esc(net.nace.reference_date)} · ${esc(net.nace.row_count)} rows</small></div>`);
 if(net?.p3dh)networkParts.push(`<div><b>P3DH</b><small>${esc(net.p3dh.row_count)} rows · ${esc(net.p3dh.framework_versions.join(', '))} · ${esc(net.p3dh.reference_dates.join(', '))}</small></div>`);
 const netHtml=`<article class="card"><h4>${esc(L('Network-/EBA-Kontext','Network/EBA context'))}</h4><p class="muted">${esc(L('Deskriptiver Kontext, keine Kausalitätsaussage. GLEIF-Rohbeziehungen werden nicht öffentlich ausgeliefert. P3DH bleibt ohne direkte Lead-Metric-Zuordnung.','Descriptive context, not causal evidence. Raw GLEIF relationships are not shipped publicly. P3DH remains without a direct lead-metric mapping.'))}</p><div class="decision-list">${networkParts.join('')||`<div class="empty">${esc(L('Kein erlaubter EBA/P3DH-Kontext für diese Institution.','No permitted EBA/P3DH context for this institution.'))}</div>`}</div></article>`;
 const covHtml=cov?`<article class="card"><h4>${esc(L('Versicherungs-Coverage v1','Insurance coverage v1'))}</h4><div class="kv"><span>${esc(L('Aktuelle Pflichtzellen','Current required cells'))}</span><b>${esc(cov.terminal)}/${esc(cov.total)}</b><span>${esc(L('Nichtterminal','Nonterminal'))}</span><b>${esc(cov.nonterminal)}</b></div>${cov.nonterminal?`<p class="guard">${esc(L('Mindestens eine Zelle bleibt absichtlich ungelöst; keine stille Wertauswahl.','At least one cell remains intentionally unresolved; no silent value selection.'))}</p>`:''}</article>`:`<article class="card"><h4>${esc(L('Versicherungs-Coverage v1','Insurance coverage v1'))}</h4><p class="muted">${esc(L('Für dieses Institut gilt der 200-Zellen-Versicherungs-Completion-Vertrag nicht.','The 200-cell insurance completion contract does not apply to this institution.'))}</p></article>`;
 const fi1Html=`<article class="card"><h4>FI1 · EPPO/OLAF</h4><div class="kv"><span>${esc(L('Globaler offizieller Fallkorpus','Global official case corpus'))}</span><b>${esc(f.case_corpus_count??0)}</b><span>${esc(L('Institutionell gebundene Seed-Kandidaten','Institution-bound seed candidates'))}</span><b>${esc(f.seed_candidate_count??0)}</b><span>${esc(L('Quellenstatus','Source status'))}</span><b>${esc(fs.status||'—')}</b><span>${esc(L('Offene Quellenlücken','Residual source gaps'))}</span><b>${esc(f.residual_source_gap_count??0)}</b></div><p class="guard">${esc(L('Der Fallkorpus ist global und keiner Institution zugeordnet. 0 institutionell gebundene Kandidaten ist keine Entwarnung und kein Screening-Ergebnis. Kein Fall wird ohne exakte Evidenz an eine Institution angehängt.','The case corpus is global and is not assigned to any institution. 0 institution-bound candidates is not clearance and is not a screening result. No case is attached to an institution without exact evidence.'))}</p><p class="muted"><b>${esc(L('Grund des Quellenstatus:','Source-state reason:'))}</b> ${esc(fs.reason||'—')}</p><p class="muted"><b>${esc(L('Rechtlich-authentische Grenze:','Legal-authenticity boundary:'))}</b> ${esc(fs.legal_authenticity_boundary||'—')}</p></article>`;
 return `<h4>${esc(L('Begrenzter statischer Analyse- und Kontextauszug','Bounded static analysis and context excerpt'))}</h4><p class="muted">${esc(L('Dieser Auszug zeigt ausschließlich die hier quellengebundenen FI1/FI2/EBA/P3DH-Kontexte. Er ersetzt nicht die weitergehenden Vergabe-, Network- oder Enforcement-Fallfunktionen, die auf dieser öffentlichen Seite weiterhin nicht verfügbar sind. Nicht Screening, nicht Risiko-Score, keine natürliche-Personen-Schicht.','This excerpt shows only the source-bound FI1/FI2/EBA/P3DH contexts exposed here. It does not replace the broader procurement, network or enforcement-case functions that remain unavailable on this public page. Not screening, not a risk score, no natural-person layer.'))}</p><div class="card-grid">${fi2Html}${netHtml}${covHtml}${fi1Html}</div>`;
}

function publicSourceLinkHtml(s){
  if(!s?.url)return'';
  let host='';
  try{host=new URL(s.url,location.href).hostname.toLowerCase()}catch(_){}
  if(host==='scor.com'||host.endsWith('.scor.com')){
    const msg=state.lang==='de'?'Bibliografisch identifiziert · Direktlink hier aus Quellenrechtsgründen nicht ausgegeben':'Bibliographically identified · direct link not emitted here for source-rights reasons';
    return`<span class="source-link-restricted">${esc(msg)}</span>`;
  }
  return`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${t('officialSource')}</a>`;
}

function runInvestigate(){const eid=$('#invEntity').value,mc=$('#invMetric').value,xs=state.snapshot.observations.filter(o=>o.entity_id===eid&&o.metric_code===mc).sort((a,b)=>(a.reference_date||'').localeCompare(b.reference_date||'')),dec=state.snapshot.time_series_decisions.filter(d=>d.entity_id===eid&&d.metric_code===mc);$('#invDossier').innerHTML=dossierHtml(eid)+entityEmptyStateHtml(eid);$('#timeSeries').innerHTML=`<h4>${t('timeSeries')} · ${esc(metricOf(mc).name||mc)}</h4>${svgSeries(xs)}<div class="decision-list">${dec.map(d=>`<div>${badge(d.comparability_status)}<span>${esc(d.period_a)} → ${esc(d.period_b)}</span><small>${esc(JSON.stringify(d.reasons_json||{}))}</small></div>`).join('')}</div>`;$('#ownership').innerHTML=`<h4>${t('ownership')}</h4>${ownershipSvg(eid)}`;$('#componentExplorer').innerHTML=`<h4>${t('components')}</h4>${componentHtml(eid)}`;$('#metricExplorer').innerHTML=`<h4>${t('metricExplorer')}</h4>${metricHtml(mc)}`;const srcs=[...new Set(state.snapshot.observations.filter(o=>o.entity_id===eid).map(o=>o.source_id))].map(sourceOf).filter(Boolean);$('#sourceBrowser').innerHTML=`<h4>${t('sourceBrowser')}</h4><div class="source-grid">${srcs.map(s=>`<article class="card"><b>${esc(s.publisher||'')}</b><div>${esc(s.title||'')}</div><small>${esc(s.source_family||'')} · ${esc(s.publication_date||'')}</small><code>${esc(s.sha256||'')}</code>${publicSourceLinkHtml(s)}</article>`).join('')}</div>${sourceQualityHtml(eid)}`;$('#fi3Context').innerHTML=fi3ContextHtml(eid);$('#researchContext').innerHTML=researchContextHtml(eid)}
function runDiscover(){const eid=$('#discEntity').value,cands=(state.snapshot.generated_discovery_candidates||[]).filter(c=>!eid||c.entity_id===eid),threads=(state.snapshot.investigation_threads||[]).filter(th=>!eid||objectContainsEntityId(th,eid));$('#discoverResult').innerHTML=`<h4>${t('candidates')}</h4><div class="candidate-grid">${cands.slice(0,120).map(c=>`<article class="candidate"><div class="eyebrow">${esc(c.kind)}</div>${badge(c.status||'EXPLORATORY_ONLY','warn')}<h4>${esc(c.question||metricOf(c.metric_code||'').name||'Candidate')}</h4><small>${esc(nameOf(c.entity_id))}${c.period_a?' · '+esc(c.period_a)+' → '+esc(c.period_b):''}</small><details class="progressive technical-candidate"><summary>${t('technicalDetails')}</summary><pre>${esc(JSON.stringify(c.countercheck_plan||c.detail||{},null,2))}</pre></details></article>`).join('')||`<div class="empty">${t('noResults')}</div>`}</div>`;$('#threadResult').innerHTML=`<h4>${t('threads')}</h4><div class="thread-list">${threads.slice(0,80).map(th=>`<article class="card"><b>${esc(th.title||th.thread_title||th.thread_id||th.id)}</b><small>${esc(th.status||'')}</small><details class="progressive technical-candidate"><summary>${t('technicalDetails')}</summary><pre>${esc(JSON.stringify(th,null,2))}</pre></details></article>`).join('')||`<div class="empty">${t('noResults')}</div>`}</div>`}
function graphHtml(g){if(!g||!g.nodes?.length)return`<div class="empty">${t('noResults')}</div>`;return`<h4>${t('evidenceGraph')}</h4><div class="evidence-nodes">${g.nodes.map(n=>`<div class="node ${esc(n.kind.toLowerCase())}"><b>${esc(n.kind)}</b><span>${esc(n.label)}</span></div>`).join('')}</div><div class="edge-list">${g.edges.map(e=>`<div>${esc(e.from)} → <b>${esc(e.type)}</b> → ${esc(e.to)}</div>`).join('')}</div>`}
function evidenceGraphLocal(oid){const o=state.snapshot.observations.find(x=>x.id===oid);if(!o)return null;const nodes=[{id:oid,kind:'OBSERVATION',label:oid}],edges=[],e=state.entityMap.get(o.entity_id),m=metricOf(o.metric_code),s=sourceOf(o.source_id);if(e){nodes.push({id:e.id,kind:'ENTITY',label:e.legal_name});edges.push({from:oid,to:e.id,type:'ABOUT_ENTITY'})}if(m){nodes.push({id:'metric:'+m.code,kind:'METRIC',label:m.name||m.code});edges.push({from:oid,to:'metric:'+m.code,type:'USES_METRIC'})}if(s){nodes.push({id:'source:'+s.id,kind:'SOURCE',label:s.title||s.id});edges.push({from:oid,to:'source:'+s.id,type:'SUPPORTED_BY'})}(state.snapshot.lineage||[]).filter(x=>x.derived_observation_id===oid).forEach(x=>{nodes.push({id:x.input_observation_id,kind:'OBSERVATION',label:x.input_observation_id});edges.push({from:x.input_observation_id,to:oid,type:x.input_role||'INPUT'})});return{nodes,edges}}
function bindGuidedNext(){$$('.guided-next').forEach(b=>b.onclick=()=>{if(b.dataset.next==='investigate'){const a=$('#cmpA')?.value,m=$('#cmpMetric')?.value;if(a){$('#invEntity').value=a;syncEntityMetric('inv');if(m&&Array.from($('#invMetric').options).some(o=>o.value===m))$('#invMetric').value=m}showMode('investigate');runInvestigate();$('#mode-investigate').scrollIntoView({behavior:'smooth',block:'start'})}else if(b.dataset.next==='audit'&&b.dataset.oid){setAuditSelectionFromObservationId(b.dataset.oid);showMode('audit');runAudit();$('#mode-audit').scrollIntoView({behavior:'smooth',block:'start'})}})}
async function runAudit(){const id=$('#auditId').value.trim();if(!id)return;let tr,g;if(state.runtime==='local'){[tr,g]=await Promise.all([api('/api/audit/trace?observation_id='+encodeURIComponent(id)),api('/api/audit/graph?observation_id='+encodeURIComponent(id))])}else{const o=state.snapshot.observations.find(x=>x.id===id);if(!o){$('#auditResult').innerHTML=`<div class="empty">${t('noResults')}</div>`;return}tr={observation:o,entity:state.entityMap.get(o.entity_id),metric:metricOf(o.metric_code),source:sourceOf(o.source_id),incoming_lineage:state.snapshot.lineage.filter(x=>x.derived_observation_id===id),outgoing_lineage:state.snapshot.lineage.filter(x=>x.input_observation_id===id),time_series_decisions:state.snapshot.time_series_decisions.filter(x=>x.entity_id===o.entity_id&&x.metric_code===o.metric_code)};g=evidenceGraphLocal(id)}const auditResolution=observationResolution(tr.observation),auditContext=observationContextLabel(tr.observation),auditPeers=auditResolution&&auditResolution.state!=='SINGLE'&&auditResolution.state!=='NONE'?`<div>${resolutionNoticeHtml(auditResolution)}<div class="card-grid">${auditResolution.observations.filter(x=>x.id!==tr.observation.id).map((o,i)=>factCard(o,rowEvidenceLabel(o,i,auditResolution.observations.length))).join('')}</div></div>`:'';$('#auditResult').innerHTML=`<div class="trace">${factCard(tr.observation,auditContext)}${auditPeers}<article class="card"><h4>${t('entity')}</h4><pre>${esc(JSON.stringify(tr.entity,null,2))}</pre></article><article class="card"><h4>${t('metric')}</h4><pre>${esc(JSON.stringify(tr.metric,null,2))}</pre></article><article class="card"><h4>${t('source')}</h4><pre>${esc(JSON.stringify(tr.source,null,2))}</pre></article><article class="card"><h4>${t('lineage')}</h4><pre>${esc(JSON.stringify({incoming:tr.incoming_lineage,outgoing:tr.outgoing_lineage},null,2))}</pre></article><article class="card"><h4>${t('decisions')}</h4><pre>${esc(JSON.stringify(tr.time_series_decisions,null,2))}</pre></article></div>`;$('#evidenceGraph').innerHTML=graphHtml(g);bindAuditLinks()}
async function runAgent(){if(state.runtime==='static')return;const q=$('#agentQ').value.trim();if(!q)return;const r=await api('/api/agent/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q})});$('#agentResult').innerHTML=`<pre>${esc(JSON.stringify(r,null,2))}</pre>`}
async function init(){state.snapshot=await loadSnapshot();state.entityMap=new Map(state.snapshot.entities.map(x=>[x.id,x]));state.metricMap=new Map(state.snapshot.metrics.map(x=>[x.code,x]));state.sourceMap=new Map(state.snapshot.sources.map(x=>[x.id,x]));$('#buildStatus').textContent='READY';if(state.runtime==='static')$$('.local-only').forEach(x=>x.style.display='none');const ents=[...state.snapshot.entities].sort((a,b)=>(a.legal_name||'').localeCompare(b.legal_name||'')),mets=[...state.snapshot.metrics].sort((a,b)=>(a.name||a.code).localeCompare(b.name||b.code));['askEntity','invEntity'].forEach(id=>fillSelect($('#'+id),ents,x=>x.id,x=>`${x.legal_name} · ${x.type}`));fillSelect($('#discEntity'),ents,x=>x.id,x=>x.legal_name,true);fillSelect($('#cmpMetric'),compareMetricItems(),x=>x.code,x=>`${x.name||x.code} · ${x.code}`);syncCompareSelectors();const auditEnts=ents.filter(e=>state.snapshot.observations.some(o=>o.entity_id===e.id));fillSelect($('#auditEntity'),auditEnts,x=>x.id,x=>`${x.legal_name} · ${x.type}`);syncAuditMetric();const types=[...new Set(ents.map(e=>e.type).filter(Boolean))].sort(),countries=[...new Set(ents.map(e=>e.country).filter(Boolean))].sort();fillSelect($('#entityTypeFilter'),types,x=>x,x=>x,true);fillSelect($('#entityCountryFilter'),countries,x=>x,x=>x,true);const first=ents[0]?.id;if(first){$('#askEntity').value=first;$('#invEntity').value=first;syncEntityMetric('ask');syncEntityMetric('inv')}renderMetrics();renderGates();renderEntityBrowser();setExpertView(false);setLang('de');updateContextBar();}
$('#modeTabs').onclick=e=>{if(e.target.dataset.mode)showMode(e.target.dataset.mode)};$('#langToggle').onclick=()=>setLang(state.lang==='de'?'en':'de');$('#viewToggle').onclick=()=>setExpertView(!state.expert);$$('.guide-card').forEach(b=>b.onclick=()=>activateGuide(b.dataset.guideMode,b.dataset.guideFocus));$$('select').forEach(el=>el.addEventListener('change',updateContextBar));$('#auditId').addEventListener('input',updateContextBar);$('#askEntity').onchange=()=>{syncEntityMetric('ask');runAsk()};$('#askShow').onclick=runAsk;$('#searchRun').onclick=runSearch;$('#searchQ').onkeydown=e=>{if(e.key==='Enter')runSearch()};$('#entityFilter').oninput=renderEntityBrowser;$('#entityTypeFilter').onchange=renderEntityBrowser;$('#entityCountryFilter').onchange=renderEntityBrowser;$('#cmpMetric').onchange=()=>{syncCompareSelectors();$('#compareResult').innerHTML=''};$('#cmpA').onchange=()=>{syncCompareSelectors();$('#compareResult').innerHTML=''};$('#cmpB').onchange=()=>{$('#compareResult').innerHTML='';updateContextBar()};$('#cmpRun').onclick=()=>runCompare([$('#cmpA').value,$('#cmpB').value]);$('#cmpCohortRun').onclick=()=>{const ids=Array.from($('#cmpCohort').selectedOptions).map(o=>o.value);if(ids.length<2){$('#compareResult').innerHTML=`<div class="empty">${t('selectAtLeastTwo')}</div>`;return}runCompare(ids)};$('#invEntity').onchange=()=>{syncEntityMetric('inv');runInvestigate()};$('#invRun').onclick=runInvestigate;$('#discRun').onclick=runDiscover;$('#auditEntity').onchange=()=>{syncAuditMetric();updateContextBar()};$('#auditMetric').onchange=()=>{syncAuditObservation();updateContextBar()};$('#auditObservation').onchange=()=>{if($('#auditObservation').value)$('#auditId').value=$('#auditObservation').value;updateContextBar()};$('#auditGuidedRun').onclick=()=>{if($('#auditObservation').value)$('#auditId').value=$('#auditObservation').value;runAudit()};$('#auditRun').onclick=runAudit;$('#auditRerun').onclick=async()=>{if(state.runtime==='static')return runAudit();const id=$('#auditId').value.trim(),r=await api('/api/rerun',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'AUDIT_TRACE',observation_id:id})});$('#auditResult').insertAdjacentHTML('afterbegin',`<div class="rerun-ok">RERUN PASS · ${esc(r.result?.observation?.id||'')}</div>`)};$('#agentRun').onclick=runAgent;
init().catch(e=>{$('#buildStatus').textContent='ERROR';document.body.insertAdjacentHTML('beforeend',`<div class="fatal">${esc(e.message)}</div>`);console.error(e)});


