function prwStatusClass(s){s=String(s||'').toUpperCase();return s==='SUPPORTED'||s==='PASS'?'good':s==='REJECTED'?'bad':'warn'}
function prwBadgeStatus(s){return badge(String(s||'').toUpperCase(),prwStatusClass(s))}
